def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(range(10), key=lambda v: sum(row.count(v) for row in grid))
    for color in range(10):
        if color == bg:
            continue
        pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        for dc in (-1, 1):
            for r, c in pts:
                if (r + 1, c + dc) not in pts or (r - 1, c - dc) in pts:
                    continue
                y, x = r + 1, c + dc
                while (y + 1, x + dc) in pts:
                    y += 1
                    x += dc
                y += 1
                x += dc
                while 0 <= y < h and 0 <= x < w and grid[y][x] == bg:
                    out[y][x] = color
                    y += 1
                    x += dc
    return out

